int main() {
    int n;
    cin >> n;
    string s;
    cin >> s;

    vector<pair<int, int>> prefix(n + 1, {0, 0});
    for (int i = 0; i < n; ++i) {
        char c = s[i];
        int dx = 0, dy = 0;
        if (c == 'U') dy = 1;
        else if (c == 'D') dy = -1;
        else if (c == 'R') dx = 1;
        else if (c == 'L') dx = -1;
        prefix[i + 1].first = prefix[i].first + dx;
        prefix[i + 1].second = prefix[i].second + dy;
    }

    map<pair<int, int>, int> countMap;
    int result = 0;
    for (int i = 0; i <= n; ++i) {
        result += countMap[prefix[i]];
        countMap[prefix[i]]++;
    }

    cout << result << endl;
    return 0;
}
