using namespace std;

int main() {
    int n;
    string s;
    cin >> n >> s;
    vector<int> dx(n+1, 0), dy(n+1, 0);
    for (int i = 0; i < n; i++) {
        dx[i+1] = dx[i];
        dy[i+1] = dy[i];
        char c = s[i];
        if (c == 'U') dy[i+1]++;
        else if (c == 'D') dy[i+1]--;
        else if (c == 'R') dx[i+1]++;
        else if (c == 'L') dx[i+1]--;
    }
    int ans = 0;
    for (int i = 0; i <= n; i++)
        for (int j = i+1; j <= n; j++)
            if (dx[i] == dx[j] && dy[i] == dy[j])
                ans++;
    cout << ans << endl;
    return 0;
}
